import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {now,time} from './resume-test-fixtures.mjs';
import {missingUnitFixture as fixture} from './repair-missing-unit-test-fixture.mjs';
import {hash} from './manifest.mjs';
import {validateMissingUnitRequest,validateMissingOriginalUnit,validateMissingUnitProducer,verifyMissingUnitEvidence,MISSING_UNIT_FILE,missingUnit} from './repair-missing-unit-policy.mjs';
import {selectMissingUnitMatrix} from './repair-missing-unit.mjs';
const clone=x=>structuredClone(x);

test('requires a closed exclusive dispatched missing whole-unit request',()=>{const f=fixture();validateMissingUnitRequest(f.inputs,'workflow_dispatch');for(const patch of [{missing_unit:''},{missing_original_run:''},{expected_sha:'moving'},{build_only:true},{diagnostics_only:true},{controller_only:true}])assert.throws(()=>validateMissingUnitRequest({...f.inputs,...patch},'workflow_dispatch'));assert.throws(()=>validateMissingUnitRequest(f.inputs,'push'));});
test('only exact original started cancellation with unavailable coverage with genuinely absent report is admitted',()=>{const f=fixture();assert.equal(validateMissingOriginalUnit({...f,plan:f.sourcePlan,unitId:f.unit.id,now}).id,f.unit.id);for(const edit of [f=>f.run.conclusion='failure',f=>f.jobs.find(j=>j.name.startsWith('test (db-')).conclusion='success',f=>f.jobs.find(j=>j.name.startsWith('test (db-')).steps[2].conclusion='success',f=>f.jobs.find(j=>j.name.startsWith('test (db-')).steps[0].conclusion='failure',f=>f.artifacts.push({name:'unit-'+f.unit.id}),f=>f.artifacts.pop(),f=>f.artifacts.push({name:'gate-evidence'}),f=>f.jobs[0].run_attempt=2]){const bad=fixture();edit(bad);assert.throws(()=>validateMissingOriginalUnit({...bad,plan:bad.sourcePlan,unitId:bad.unit.id,now}));}});
test('selector retains complete plan and only schedules exact original singleton',()=>{const f=fixture();const input={...f,plan:f.plan,originalPlan:f.sourcePlan,event:'workflow_dispatch'};/* selector uses live-clock freshness */const shift=Date.now()-now;for(const key of ['created_at','updated_at'])input.run[key]=new Date(Date.parse(input.run[key])+shift).toISOString();assert.deepEqual(selectMissingUnitMatrix(input),{unit:[f.unit.id]});const bad=clone(input);bad.plan.execution.workers=1;delete bad.plan.fingerprint;bad.plan.fingerprint=hash(bad.plan);assert.throws(()=>selectMissingUnitMatrix(bad));});
test('fresh producer authenticates exact original native workflow topology and two bounded artifacts',()=>{const f=fixture();validateMissingUnitProducer({run:f.freshRun,jobs:f.freshJobs,artifacts:f.freshArtifacts,expected:f.expected,now});for(const edit of [f=>f.freshRun.head_sha='0'.repeat(40),f=>f.freshJobs.pop(),f=>f.freshArtifacts.push({...f.freshArtifacts[0],id:4000,name:'gate-evidence'}),f=>f.freshJobs.find(j=>j.name==='build').conclusion='success',f=>f.freshArtifacts[1].workflow_run.id=999,f=>f.freshJobs.find(j=>j.name.startsWith('test (')).steps[0].conclusion='failure']){const bad=fixture();edit(bad);assert.throws(()=>validateMissingUnitProducer({run:bad.freshRun,jobs:bad.freshJobs,artifacts:bad.freshArtifacts,expected:bad.expected,now}));}});
test('fresh whole unit supplies PASS while historical same-blob cases supply inventory only',()=>{const f=fixture();const r=verifyMissingUnitEvidence({sourcePlan:f.sourcePlan,plan:f.plan,missing:f.unit.id,proof:f.proof,now});assert.equal(r.tests,1);assert.equal(r.priorExpectationUsedAsPass,false);assert.equal(r.originalApplicationCoverage,'UNAVAILABLE_NO_ORIGINAL_UNIT_ARTIFACT');assert.equal(r.releaseAuthorized,false);assert.equal(r.expectation.runId,50);});
test('refuses any missing coverage, altered blob/case, stale font or mixed PostgreSQL identity',()=>{for(const edit of [f=>f.proof.fileBlob.candidate='2'.repeat(40),f=>f.proof.report.batches[0].result.testResults[0].assertionResults[0].fullName='renamed',f=>f.proof.report.batches[0].result.testResults[0].assertionResults=[],f=>f.proof.report.batches[0].result.numPendingTests=1,f=>f.proof.report.exitCode=1,f=>f.proof.font.candidate=f.sourcePlan.sha,f=>f.proof.font.transport.signaturePolicyUnchanged=false,f=>f.proof.font.steps[0].status=1,f=>f.proof.report.databaseTerminalEvidence.name='foreign',f=>f.proof.report.batches[0].databaseEvidence.settings.serverVersionNum='150010',f=>f.proof.report.healthAfter.ok=false,f=>f.proof.expectation.report.fingerprint='forged',f=>f.proof.expectation.report.exitCode=1,f=>f.proof.expectation.report.batches[0].result.testResults[0].assertionResults[0].status='failed']){const f=fixture();edit(f);assert.throws(()=>verifyMissingUnitEvidence({sourcePlan:f.sourcePlan,plan:f.plan,missing:f.unit.id,proof:f.proof,now}));}});
test('workflow keeps canonical full CI owner, fixed font setup, complete run-unit and no verify/build in missing mode',()=>{const s=readFileSync(new URL('../workflows/alpha-staging.yml',import.meta.url),'utf8');assert(s.startsWith('name: alpha-staging-ci\n'));for(const x of ['node ../automation/.github/ci/repair-missing-unit.mjs "$RUNNER_TEMP/ci-plan.json"','node ../automation/.github/ci/run-unit.mjs "$UNIT" "$RUNNER_TEMP/aihr-ci"','Source-bound fixed HTTPS fonts for missing whole unit','inputs.missing_unit == \'\'','!inputs.missing_unit'])assert(s.includes(x));assert(!s.includes('AIHR_CI_MISSING_UNIT_BYPASS'));});

test('preserves real cancelled-run step shape and rejects additional absence or foreign source topology',()=>{
 const f=fixture(),target=f.jobs.find(j=>j.name===`test (${f.unit.id})`);assert.equal(target.status,'completed');assert.equal(target.conclusion,'cancelled');assert.equal(target.steps[2].status,'in_progress');assert.equal(target.steps[2].conclusion,null);
 assert(!f.jobs.some(j=>['verify','deployment-hold'].includes(j.name)));validateMissingOriginalUnit({...f,plan:f.sourcePlan,unitId:f.unit.id,now});
 const two=fixture();two.artifacts=two.artifacts.filter(a=>a.name!=='unit-'+two.sourcePlan.units.find(u=>u.id!==two.unit.id).id);assert.throws(()=>validateMissingOriginalUnit({...two,plan:two.sourcePlan,unitId:two.unit.id,now}));
 const foreignBase=fixture();for(const plan of [foreignBase.plan,foreignBase.proof.freshPlan]){plan.migrationBase='0'.repeat(40);delete plan.fingerprint;plan.fingerprint=hash(plan);}assert.throws(()=>verifyMissingUnitEvidence({sourcePlan:foreignBase.sourcePlan,plan:foreignBase.plan,missing:foreignBase.unit,proof:foreignBase.proof,now}));
 const badController=fixture();badController.sourcePlan.controller='0'.repeat(40);delete badController.sourcePlan.fingerprint;badController.sourcePlan.fingerprint=hash(badController.sourcePlan);assert.throws(()=>validateMissingOriginalUnit({...badController,plan:badController.sourcePlan,unitId:badController.unit.id,now}));
 for(const edit of [f=>f.plan.migrationBase='0'.repeat(40),f=>f.plan.sha='0'.repeat(40),f=>f.proof.source.controller='0'.repeat(40),f=>f.proof.expectation.metadata.jobs[0].conclusion='failure',f=>f.proof.producer.steps[1].conclusion='failure',f=>f.proof.producer.steps[0].completed_at=time(2.1)]){
  const bad=fixture();edit(bad);assert.throws(()=>verifyMissingUnitEvidence({sourcePlan:bad.sourcePlan,plan:bad.plan,missing:bad.unit,proof:bad.proof,now}));
 }
});
